    <p class="countdown">إعادة الإرسال خلال 0:45</p>

    <button class="verify-btn" disabled>تحقق</button>
  </div>

  <script>
    const inputs = document.querySelectorAll('.code-inputs input');
    const verifyBtn = document.querySelector('.verify-btn');
    const countdownEl = document.querySelector('.countdown');

    let seconds = 45;

    const updateCountdown = () => {
      const m = String(Math.floor(seconds / 60)).padStart(2, '0');
      const s = String(seconds % 60).padStart(2, '0');
      countdownEl.textContent = `إعادة الإرسال خلال ${m}:${s}`;
    };

    const interval = setInterval(() => {
      seconds--;
      if (seconds <= 0) {
        clearInterval(interval);
        countdownEl.textContent = 'لم يصل الرمز؟ أعد الإرسال';
        verifyBtn.disabled = false;
      } else {
        updateCountdown();
      }
    }, 1000);

    updateCountdown();

    inputs.forEach((input, index) => {
      input.addEventListener('input', () => {
        if (input.value.length === 1 && index < inputs.length - 1) {
          inputs[index + 1].focus();
        }
        if (input.value.length === 0 && index > 0) {
          inputs[index - 1].focus();
        }
        const allFilled = Array.from(inputs).every(i => i.value.length === 1);
        verifyBtn.disabled = !allFilled || seconds > 0;
      });

      input.addEventListener('keydown', (e) => {
        if (e.key === 'Backspace' && input.value.length === 0 && index > 0) {
          inputs[index - 1].focus();
        }
      });
    });
  </script>
</body>
</html>
